<script setup>import{onMounted,ref}from'vue';import{congeService}from'@/services/congeService';const demandes=ref([]),err=ref('');async function load(){try{demandes.value=await congeService.aValider()}catch(e){err.value=e.response?.data?.message||'Accès refusé.'}}async function decision(d,statut){const commentaire=prompt(statut==='VALIDEE'?'Commentaire de validation :':'Motif du refus :','');try{const x=await congeService.decision(d.id,{statut,commentaire});d.statut=x.statut}catch(e){err.value=e.response?.data?.message||'Opération impossible.'}}onMounted(load)</script>
<template><div class="container-fluid py-4"><h1 class="h3">Validation des congés</h1><p v-if="err" class="alert alert-danger">{{err}}</p><section class="card card-body"><div v-for="d in demandes" :key="d.id" class="border-bottom py-3 d-flex justify-content-between align-items-center"><div><strong>{{d.employe?.prenom}} {{d.employe?.nom}}</strong><div>{{d.typeConge}} · {{d.dateDebut}} → {{d.dateFin}} · {{d.joursDemandes}} jour(s)</div><small>{{d.motif||'Sans motif'}}</small></div><div class="text-end"><span class="badge text-bg-warning mb-2">{{d.statut}}</span><div><button class="btn btn-sm btn-success me-2" :disabled="d.statut!=='EN_ATTENTE'" @click="decision(d,'VALIDEE')">Valider</button><button class="btn btn-sm btn-outline-danger" :disabled="d.statut!=='EN_ATTENTE'" @click="decision(d,'REFUSEE')">Refuser</button></div></div></div><p v-if="!demandes.length" class="text-body-secondary">Aucune demande en attente.</p></section></div></template>
